use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StockError {
    UnknownSku(String),
    Insufficient {
        sku: String,
        requested: u32,
        available: u32,
    },
}

/// Stock levels per SKU. A SKU becomes known the first time it is received.
#[derive(Debug, Clone, Default)]
pub struct Inventory {
    on_hand: BTreeMap<String, u32>,
}

impl Inventory {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn receive(&mut self, sku: &str, qty: u32) {
        let level = self.on_hand.entry(sku.to_string()).or_insert(0);
        *level = level.saturating_add(qty);
    }

    pub fn ship(&mut self, sku: &str, qty: u32) -> Result<(), StockError> {
        let level = self
            .on_hand
            .get_mut(sku)
            .ok_or_else(|| StockError::UnknownSku(sku.to_string()))?;
        if qty > *level {
            return Err(StockError::Insufficient {
                sku: sku.to_string(),
                requested: qty,
                available: *level,
            });
        }
        *level -= qty;
        Ok(())
    }

    pub fn on_hand(&self, sku: &str) -> u32 {
        self.on_hand.get(sku).copied().unwrap_or(0)
    }

    /// Known SKUs in ascending order.
    pub fn skus(&self) -> Vec<&str> {
        self.on_hand.keys().map(String::as_str).collect()
    }
}

