use fixture::report::stock_report;
use fixture::{Inventory, StockError};

fn insufficient(sku: &str, requested: u32, available: u32) -> StockError {
    StockError::Insufficient { sku: sku.to_string(), requested, available }
}

fn not_reserved(sku: &str, requested: u32, reserved: u32) -> StockError {
    StockError::NotReserved { sku: sku.to_string(), requested, reserved }
}

fn levels(inventory: &Inventory, sku: &str) -> (u32, u32, u32) {
    (inventory.on_hand(sku), inventory.reserved(sku), inventory.available(sku))
}

#[test]
fn reserve_and_release() {
    let mut inventory = Inventory::new();
    inventory.receive("apple", 5);
    inventory.reserve("apple", 2).unwrap();
    assert_eq!(levels(&inventory, "apple"), (5, 2, 3));
    assert_eq!(inventory.reserve("apple", 4), Err(insufficient("apple", 4, 3)));
    assert_eq!(levels(&inventory, "apple"), (5, 2, 3));
    inventory.reserve("apple", 3).unwrap();
    assert_eq!(levels(&inventory, "apple"), (5, 5, 0));
    assert_eq!(inventory.release("apple", 6), Err(not_reserved("apple", 6, 5)));
    inventory.release("apple", 4).unwrap();
    assert_eq!(levels(&inventory, "apple"), (5, 1, 4));
    inventory.reserve("apple", 0).unwrap();
    inventory.release("apple", 0).unwrap();
    assert_eq!(levels(&inventory, "apple"), (5, 1, 4));
}

#[test]
fn ship_uses_only_available_stock() {
    let mut inventory = Inventory::new();
    inventory.receive("pear", 10);
    inventory.reserve("pear", 7).unwrap();
    assert_eq!(inventory.ship("pear", 4), Err(insufficient("pear", 4, 3)));
    assert_eq!(levels(&inventory, "pear"), (10, 7, 3));
    inventory.ship("pear", 3).unwrap();
    assert_eq!(levels(&inventory, "pear"), (7, 7, 0));
    inventory.receive("pear", 2);
    assert_eq!(levels(&inventory, "pear"), (9, 7, 2));
}

#[test]
fn ship_reserved_consumes_the_reservation() {
    let mut inventory = Inventory::new();
    inventory.receive("fig", 6);
    inventory.reserve("fig", 4).unwrap();
    assert_eq!(inventory.ship_reserved("fig", 5), Err(not_reserved("fig", 5, 4)));
    assert_eq!(levels(&inventory, "fig"), (6, 4, 2));
    inventory.ship_reserved("fig", 3).unwrap();
    assert_eq!(levels(&inventory, "fig"), (3, 1, 2));
    inventory.ship_reserved("fig", 0).unwrap();
    inventory.ship_reserved("fig", 1).unwrap();
    assert_eq!(levels(&inventory, "fig"), (2, 0, 2));
    assert_eq!(inventory.ship_reserved("fig", 1), Err(not_reserved("fig", 1, 0)));
}

#[test]
fn unknown_skus() {
    let mut inventory = Inventory::new();
    inventory.receive("apple", 1);
    let unknown = || Err(StockError::UnknownSku("kiwi".to_string()));
    assert_eq!(inventory.reserve("kiwi", 0), unknown());
    assert_eq!(inventory.release("kiwi", 0), unknown());
    assert_eq!(inventory.ship("kiwi", 0), unknown());
    assert_eq!(inventory.ship_reserved("kiwi", 1), unknown());
    assert_eq!(levels(&inventory, "kiwi"), (0, 0, 0));
    assert_eq!(inventory.skus(), ["apple"]);
}

#[test]
fn report_shows_reservations() {
    let mut inventory = Inventory::new();
    assert_eq!(stock_report(&inventory), "");
    inventory.receive("pear", 1);
    inventory.receive("apple", 5);
    inventory.reserve("apple", 2).unwrap();
    assert_eq!(
        stock_report(&inventory),
        "apple: 5 on hand, 2 reserved, 3 available\npear: 1 on hand, 0 reserved, 1 available\n"
    );
    inventory.ship_reserved("apple", 2).unwrap();
    inventory.ship("apple", 3).unwrap();
    assert_eq!(
        stock_report(&inventory),
        "apple: 0 on hand, 0 reserved, 0 available\npear: 1 on hand, 0 reserved, 1 available\n"
    );
}
